{
  "decision-railway-junction-removal": "WITH RECURSIVE junctions(j) AS (SELECT end_a FROM tracks UNION SELECT end_b FROM tracks), edges(src,dst) AS (SELECT end_a,end_b FROM tracks UNION ALL SELECT end_b,end_a FROM tracks), reach(removed,start,node) AS (SELECT r.j,s.j,s.j FROM junctions AS r CROSS JOIN junctions AS s WHERE s.j <> r.j UNION SELECT p.removed,p.start,e.dst FROM reach AS p JOIN edges AS e ON e.src = p.node WHERE e.dst <> p.removed), labels AS (SELECT removed,start,MIN(node COLLATE BINARY) AS representative FROM reach GROUP BY removed,start) SELECT removed AS junction,COUNT(*) AS components FROM labels WHERE start = representative COLLATE BINARY GROUP BY removed HAVING COUNT(*) >= 2 ORDER BY junction COLLATE BINARY ASC",
  "decision-ration-sealed-refill-packs": "WITH counts(n) AS (VALUES (0),(1),(2),(3),(4),(5),(6)), options AS (SELECT x.n*a.pack_units AS units_a,y.n*b.pack_units AS units_b,a.need_units AS need_a,b.need_units AS need_b,r.free_units,r.note_id AS release_note,a.slip_id AS slip_a,b.slip_id AS slip_b FROM stock_release AS r CROSS JOIN bay_slip AS a CROSS JOIN bay_slip AS b CROSS JOIN counts AS x CROSS JOIN counts AS y WHERE a.bay_id = 'A' AND b.bay_id = 'B') SELECT units_a,units_b,release_note,slip_a,slip_b FROM options WHERE units_a <= need_a AND units_b <= need_b AND units_a+units_b <= free_units ORDER BY MIN(units_a*need_b,units_b*need_a) DESC,units_a+units_b DESC,units_a DESC LIMIT 1",
  "decision-ration-swap-pack-charging": "WITH RECURSIVE masks(m) AS (VALUES (0) UNION ALL SELECT m+1 FROM masks WHERE m < 15), totals AS (SELECT m,COALESCE(SUM(p.need_kwh),0) AS energy,COALESCE(SUM(p.trip_count),0) AS trips,COALESCE(SUM(p.pack_bit),0) AS selected_bits FROM masks LEFT JOIN pack_job AS p ON (m & p.pack_bit) <> 0 GROUP BY m), best AS (SELECT t.selected_bits,s.source_id FROM totals AS t CROSS JOIN shift_notice AS s WHERE t.energy <= s.allot_kwh ORDER BY t.trips DESC,t.energy ASC,t.selected_bits ASC LIMIT 1) SELECT b.source_id,p.pack_name,p.need_kwh,p.trip_count FROM best AS b JOIN pack_job AS p ON (b.selected_bits & p.pack_bit) <> 0 ORDER BY p.pack_bit ASC",
  "decision-rebalance-chilled-trailer-bays": "WITH masks(blue_mask) AS (VALUES (0),(1),(2),(3),(4),(5),(6),(7)), assignments AS (SELECT m.blue_mask,l.pallets,l.initial_bay,CASE WHEN (m.blue_mask & l.lot_bit) <> 0 THEN 'blue' ELSE 'gold' END AS final_bay FROM masks AS m CROSS JOIN lot_manifest AS l), totals AS (SELECT blue_mask,SUM(CASE WHEN final_bay = 'blue' THEN pallets ELSE 0 END) AS blue_pallets,SUM(CASE WHEN final_bay = 'gold' THEN pallets ELSE 0 END) AS gold_pallets,SUM(CASE WHEN final_bay <> initial_bay THEN pallets ELSE 0 END) AS handled_pallets FROM assignments GROUP BY blue_mask) SELECT blue_mask,blue_pallets,gold_pallets,handled_pallets FROM totals CROSS JOIN bay_limits WHERE blue_pallets <= blue_cap AND gold_pallets <= gold_cap ORDER BY handled_pallets ASC,blue_mask ASC LIMIT 1"
}
